with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'التحليل الديناميكي المتقدم والتنبؤ الممتد','الدوامية الكامنة ونظرية شبه الجيوستروفية والحركة الرأسية والتكوّن الجبهي والأنهار الجوية والانسداد والمنخفضات المعزولة وقابلية التنبؤ.',21,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'ديناميكية الغلاف الجوي المتقدمة',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التنبؤ الممتد وقابلية التنبؤ',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('potential-vorticity-and-atmospheric-dynamics','الدوامية الكامنة وتطبيقاتها في التحليل الجوي','مفهوم الدوامية الكامنة وحفظها وتفسير الاضطرابات الديناميكية.','{"blocks":[{"type":"text","text":"تجمع الدوامية الكامنة بين الدوران والطبقات الحرارية والاستقرار الرأسي في كمية ديناميكية مفيدة لتحليل الغلاف الجوي."},{"type":"text","text":"تستخدم صيغ مختلفة للدوامية الكامنة بحسب الإحداثيات والتقريبات، ومن أشهرها صياغة إرتل."},{"type":"text","text":"ترتبط الدوامية الكامنة بتمدد أو انضغاط عمود الهواء وبالتغيرات في الدوران والاستقرار."},{"type":"text","text":"في جريان أديباتي عديم الاحتكاك تقريباً، تحفظ الدوامية الكامنة على طول مسار الجسيم الهوائي وفق الافتراضات المناسبة."},{"type":"text","text":"تؤدي التسخينات غير الأديباتية والاحتكاك والخلط إلى تغير الدوامية الكامنة."},{"type":"text","text":"تستخدم خرائط الدوامية الكامنة لتتبع الاضطرابات الستراتوسفيرية-التروبوسفيرية والتداخل بين الطبقات."},{"type":"text","text":"قد يرتبط امتداد الدوامية الكامنة نحو الأسفل بتطور استجابة سطحية، لكن النتيجة تعتمد على البيئة والتفاعل الديناميكي."},{"type":"text","text":"تساعد المقاطع الرأسية على رؤية ميل الاضطراب وتوزيع الدوامية والاستقرار مع الارتفاع."},{"type":"text","text":"تستخدم الدوامية الكامنة في تفسير بعض عمليات التكوّن الجبهي وتطور المنخفضات والاضطرابات العلوية."},{"type":"text","text":"يجب معرفة مستوى الإحداثيات والوحدة والتعريف المستخدم قبل مقارنة خرائط الدوامية الكامنة."},{"type":"text","text":"مثال: تتبع شذوذ دوامية كامنة في الطبقات العليا مع خرائط الحرارة والرطوبة يساعد في تشخيص تطور اضطراب جوي."},{"type":"callout","text":"خلاصة: الدوامية الكامنة أداة متقدمة تربط الدوران والاستقرار والتسخين في تحليل واحد."}]}',1360,60,'["تعريف الدوامية الكامنة","فهم حفظها في ظروف مثالية","تطبيقها في تحليل الاضطرابات"]','ديناميكية الغلاف الجوي المتقدمة'),
('quasigeostrophic-theory','نظرية شبه الجيوستروفية وتوازن الحركة واسعة النطاق','تقريبات الحركة واسعة النطاق وعلاقتها بالدوامية والحركة الرأسية.','{"blocks":[{"type":"text","text":"تصف نظرية شبه الجيوستروفية جزءاً من الحركة الجوية واسعة النطاق عندما يكون الجريان قريباً من التوازن الجيوستروفي."},{"type":"text","text":"تفترض النظرية عادة أن عدد روسبي صغير نسبياً وأن الانحراف عن التوازن الأساسي محدود."},{"type":"text","text":"تستخدم الرياح الجيوستروفية كحالة أولية، ثم تدرس الانحرافات العمرانية التي ترتبط بتطور الأنظمة الجوية."},{"type":"text","text":"تربط النظرية تطور الدوامية الجيوستروفية بتأثير الحركة الرأسية والتباعد والتغيرات الحرارية."},{"type":"text","text":"تساعد معادلة الدوامية شبه الجيوستروفية في تفسير نمو الأخاديد والنتوءات والمنخفضات واسعة النطاق."},{"type":"text","text":"تربط معادلة أوميغا الحركة الرأسية بتوزيع الدوامية والأدفكشن الحراري في صياغة شبه جيوستروفية."},{"type":"text","text":"تكون النظرية أقل ملاءمة قرب خط الاستواء وفي الحمل العميق والظواهر الصغيرة ذات التسارع القوي."},{"type":"text","text":"تستخدم النظرية إطاراً تفسيرياً للتحليل السينوبتيكي، وليست بديلاً عن النماذج العددية الكاملة."},{"type":"text","text":"تساعد على فهم العلاقة بين الرفع الديناميكي وتطور السحب والهطول في الأنظمة واسعة النطاق."},{"type":"text","text":"تتطلب التطبيقات معرفة مستويات الضغط والحرارة والرياح والدوامية وتدرجاتها الأفقية."},{"type":"text","text":"مثال: تداخل أدفكشن الدوامية مع الأدفكشن الحراري قد يدعم حركة صاعدة في منطقة من الأخدود، بحسب البنية الرأسية."},{"type":"callout","text":"خلاصة: نظرية شبه الجيوستروفية توفر تفسيراً ديناميكياً للأنظمة واسعة النطاق ضمن افتراضات محددة."}]}',1370,60,'["شرح افتراضات شبه الجيوستروفية","فهم توازن الحركة واسعة النطاق","تحديد حدود صلاحية النظرية"]','ديناميكية الغلاف الجوي المتقدمة'),
('omega-equation-and-vertical-motion','معادلة أوميغا والحركة الرأسية في الغلاف الجوي','تفسير السرعة الرأسية في الإحداثيات الضغطية ومصادر الرفع والهبوط.','{"blocks":[{"type":"text","text":"في الإحداثيات الضغطية يرمز أوميغا إلى التغير الزمني للضغط مع حركة الحزمة، ويعبر عن السرعة الرأسية الضغطية."},{"type":"text","text":"تستخدم الإشارة السالبة لأوميغا عادة للدلالة على الحركة الصاعدة، لأن الضغط ينخفض مع الارتفاع."},{"type":"text","text":"تستخدم الإشارة الموجبة لأوميغا للدلالة على الحركة الهابطة في الاصطلاح المعتاد."},{"type":"text","text":"قد تنشأ الحركة الصاعدة من التقارب في الطبقات السفلى والتباعد في الطبقات العليا، أو من الرفع الجبهي والتضاريسي والحمل الحراري."},{"type":"text","text":"تربط معادلة أوميغا شبه الجيوستروفية الحركة الرأسية بتوزيع الدوامية والحرارة في المجال الأفقي."},{"type":"text","text":"تساعد خرائط أوميغا عند 700 أو 500 hPa في تحديد مناطق الرفع والهبوط، مع الانتباه إلى تعريف الوحدة والإشارة."},{"type":"text","text":"لا يعني الرفع وحده هطولاً؛ إذ يلزم توفر الرطوبة والاستقرار المناسب وعمق طبقة الرفع."},{"type":"text","text":"تتأثر خرائط الحركة الرأسية بدقة النموذج والتمثيل الفيزيائي والتدرجات المحسوبة."},{"type":"text","text":"تختلف الحركة الرأسية واسعة النطاق عن التيارات الصاعدة القوية داخل السحب الحملية، فهي مقاييس وسرعات مختلفة."},{"type":"text","text":"ينبغي مقارنة أوميغا مع الرطوبة والحرارة والدوامية والخرائط السطحية لتفسير الحالة."},{"type":"text","text":"مثال: منطقة أوميغا سالبة ورطوبة متوسطة مرتفعة قد تكون بيئة داعمة للسحب، لكن التقييم يحتاج بيانات إضافية."},{"type":"callout","text":"خلاصة: الحركة الرأسية حلقة وصل بين الديناميكية واسعة النطاق وتطور السحب والهطول."}]}',1380,60,'["شرح إشارة أوميغا","تمييز الرفع الديناميكي والحراري","تفسير خرائط الحركة الرأسية"]','ديناميكية الغلاف الجوي المتقدمة'),
('frontogenesis-and-frontolysis','التكوّن الجبهي واضمحلال الجبهات الهوائية','تغير التدرجات الحرارية والقص والتشوه الأفقي في المناطق الجبهية.','{"blocks":[{"type":"text","text":"يشير التكوّن الجبهي Frontogenesis إلى زيادة حدة التدرج الأفقي لدرجة الحرارة أو الكثافة في منطقة انتقالية."},{"type":"text","text":"يشير اضمحلال الجبهة Frontolysis إلى ضعف التدرج الحراري الأفقي وتراجع حدة المنطقة الجبهية."},{"type":"text","text":"تؤثر حقول التشوه والقص والتمدد والانكماش في إعادة تنظيم خطوط الحرارة وتكوين الجبهات."},{"type":"text","text":"قد يؤدي التشوه الأفقي إلى تقارب خطوط تساوي الحرارة وزيادة التدرج في اتجاه معين."},{"type":"text","text":"ينشأ دوران ثانوي قرب الجبهة استجابة للتوازن الديناميكي، وقد يدعم حركة صاعدة في منطقة محددة."},{"type":"text","text":"تساعد المقاطع الرأسية على تحديد الميل الجبهي والقص الحراري والحركة الرأسية المرتبطة به."},{"type":"text","text":"قد تتعزز السحب والهطولات على طول مناطق التكوّن الجبهي إذا توافرت الرطوبة والرفع."},{"type":"text","text":"تتأثر الجبهات بالتضاريس والاحتكاك والخلط والحرارة السطحية والتفاعلات مع الأنظمة العلوية."},{"type":"text","text":"تستخدم خرائط التدرج الحراري والدوامية والتباعد والحركة الرأسية لتشخيص مناطق التكوّن الجبهي."},{"type":"text","text":"لا يتطابق التكوّن الجبهي دائماً مع ظهور جبهة سطحية واضحة؛ فقد يحدث في طبقات أعلى."},{"type":"text","text":"مثال: ازدياد تقارب خطوط الحرارة مع وجود رطوبة ورفع قد يشير إلى تقوية منطقة جبهية وهطول منظم."},{"type":"callout","text":"خلاصة: التكوّن الجبهي يفسر كيف تتشكل الجبهات وتتغير شدتها بفعل الحركة الديناميكية."}]}',1390,60,'["تعريف التكوّن الجبهي","فهم التشوه والقص الحراري","تمييز التكوّن عن الاضمحلال"]','ديناميكية الغلاف الجوي المتقدمة'),
('atmospheric-rivers-and-moisture-transport','الأنهار الجوية ونقل الرطوبة واسع النطاق','ممرات النقل المكثف لبخار الماء ودورها في الهطول الغزير.','{"blocks":[{"type":"text","text":"النهر الجوي ممر جوي طويل وضيّق نسبياً ينقل كميات كبيرة من بخار الماء ضمن تدفق جوي واسع."},{"type":"text","text":"يرتبط كثير من الأنهار الجوية بالرياح القوية في الطبقات السفلى والمتوسطة وبأنظمة المنخفضات والجبهات."},{"type":"text","text":"يستخدم تكامل النقل الرأسي لبخار الماء لتقدير شدة تدفق الرطوبة عبر مقطع رأسي."},{"type":"text","text":"قد تتسبب الأنهار الجوية في هطول غزير عندما تتفاعل مع الجبهات أو التضاريس أو الرفع الديناميكي."},{"type":"text","text":"تؤثر مدة بقاء ممر الرطوبة فوق منطقة واحدة في كمية الهطول المتراكمة."},{"type":"text","text":"قد تحمل الأنهار الجوية أمطاراً مفيدة للمخزون المائي، لكنها قد ترتبط أيضاً بمخاطر فيضانات وانهيارات بحسب الظروف."},{"type":"text","text":"تتغير خصائص النهر الجوي من حيث الطول والعرض والرطوبة والسرعة والتوقيت، ولا تكفي تسمية واحدة لتحديد الأثر."},{"type":"text","text":"تستخدم بيانات بخار الماء المتكامل والرياح والأقمار والنماذج لتحديد الممرات ومتابعة انتقالها."},{"type":"text","text":"تساعد المقارنة بين النقل الرطوبي والرفع التضاريسي على تقدير مناطق الهطول الأشد."},{"type":"text","text":"قد تختلف آثار النهر الجوي على جانبي سلسلة جبلية بسبب اتجاه التدفق والظل المطري."},{"type":"text","text":"مثال: وصول ممر رطوبة قوي إلى سفح جبلي مواجه للرياح قد يعزز هطولاً مستمراً عند توافر الرفع."},{"type":"callout","text":"خلاصة: الأنهار الجوية تربط النقل بعيد المدى لبخار الماء بمخاطر الهطول والموارد المائية."}]}',1400,60,'["تعريف النهر الجوي","فهم النقل المتكامل لبخار الماء","تحليل الرفع والهطول التضاريسي"]','ديناميكية الغلاف الجوي المتقدمة'),
('atmospheric-blocking-and-persistent-patterns','الانسداد الجوي والأنماط الجوية المستمرة','المرتفعات المعطلة وتباطؤ انتقال الأنظمة واستمرار موجات الطقس.','{"blocks":[{"type":"text","text":"الانسداد الجوي نمط واسع النطاق من الدوران يعوق أو يغير المسار المعتاد للرياح الغربية والأنظمة الجوية."},{"type":"text","text":"قد يظهر الانسداد على شكل مرتفع قوي شبه ثابت أو نمط مزدوج من المرتفعات والمنخفضات."},{"type":"text","text":"يسهم الانسداد في إبطاء انتقال الأنظمة الجوية، ما قد يطيل فترة الحرارة أو البرودة أو الجفاف أو الهطول في بعض المناطق."},{"type":"text","text":"تختلف آليات نشأة الانسداد، وقد تشمل تضخيم موجات روسبي وتفاعلات الدوامات مع التدفق الأساسي."},{"type":"text","text":"تستخدم خرائط الارتفاع الجيوپوتنسيالي والدوامية والضغط لتحديد الأنماط المعطلة ومتابعة تطورها."},{"type":"text","text":"قد يستمر الانسداد أياماً أو أسابيع وفق تعريف المؤشر وطبيعة الحالة."},{"type":"text","text":"لا يعني كل مرتفع جوي انسداداً؛ إذ يتطلب التشخيص نمطاً مكانياً وزمنياً مناسباً."},{"type":"text","text":"تؤثر الانسدادات في مسارات المنخفضات والعواصف وتوزيع الحرارة والهطول على نطاق واسع."},{"type":"text","text":"قد تتفاعل الانسدادات مع التيارات النفاثة والثلوج البحرية والأنماط المحيطية."},{"type":"text","text":"تحتاج التوقعات الممتدة إلى تقييم احتمال نشوء الانسداد واستمراره وانحلاله عبر مجموعات النماذج."},{"type":"text","text":"مثال: استمرار مرتفع محصور قد يطيل موجة حر إذا تزامن مع هبوط هوائي وسماء صافية وجفاف سطحي."},{"type":"callout","text":"خلاصة: الانسداد يفسر استمرار بعض الحالات الجوية وتراكم آثارها عبر الزمن."}]}',1410,60,'["شرح الانسداد الجوي","فهم استمرار الأنماط","ربط الانسداد بالتطرفات الجوية"]','ديناميكية الغلاف الجوي المتقدمة'),
('cutoff-lows-and-upper-level-lows','المنخفضات المعزولة والمنخفضات الباردة في الطبقات العليا','انفصال الدوامات العلوية وتطور المنخفضات الباردة والهطول المرتبط بها.','{"blocks":[{"type":"text","text":"المنخفض العلوي المعزول Cut-off Low اضطراب مغلق في الطبقات العليا ينفصل جزئياً عن التيار الغربي السائد."},{"type":"text","text":"قد يتكون عندما تتضخم موجة روسبي ويحدث انغلاق لخطوط الارتفاع حول مركز منخفض علوي."},{"type":"text","text":"يرتبط المنخفض البارد العلوي بانخفاض درجات الحرارة في الطبقات الوسطى أو العليا مقارنة بالمحيط."},{"type":"text","text":"قد يزيد الهواء البارد في الطبقات العليا من التدرج الحراري الرأسي وعدم الاستقرار إذا بقيت الطبقات السفلى دافئة ورطبة."},{"type":"text","text":"تتأثر حركة المنخفض المعزول بضعف التوجيه العام، وقد يصبح بطيئاً أو شبه ثابت في بعض الحالات."},{"type":"text","text":"قد ينتج عنه هطول متكرر أو عواصف حملية محلية عند توفر الرطوبة والرفع وعدم الاستقرار."},{"type":"text","text":"تساعد خرائط 500 hPa ودرجة الحرارة والدوامية والحركة الرأسية على تشخيص المنخفض ومتابعة موقعه."},{"type":"text","text":"قد يصعب توقع توقيت تحرك المنخفض المعزول بسبب حساسية مساره للتدفق المحيط والتفاعلات المحلية."},{"type":"text","text":"لا يعني وجود منخفض علوي بالضرورة هطولاً واسعاً؛ إذ يعتمد الأثر على الرطوبة والتضاريس والطبقة السفلى."},{"type":"text","text":"تستخدم صور الأقمار والرادار والسبر لتقييم التطور الفعلي مقارنة بمخرجات النماذج."},{"type":"text","text":"مثال: منخفض علوي بارد فوق بحر دافئ نسبياً قد يدعم عدم استقرار وحملاً محلياً إذا توافرت الرطوبة."},{"type":"callout","text":"خلاصة: المنخفضات المعزولة أنظمة حساسة المسار قد تنتج حالات مطرية طويلة أو حملية محلية."}]}',1420,60,'["شرح المنخفض العلوي المعزول","فهم الانفصال عن التيار الغربي","تحليل أثر الهواء البارد العلوي"]','ديناميكية الغلاف الجوي المتقدمة'),
('tropical-extratropical-interaction','تفاعل الأنظمة المدارية وخارج المدارية','الانتقال المداري-خارج المداري وتفاعل الرطوبة والدوامية والقص.','{"blocks":[{"type":"text","text":"قد تتفاعل الأنظمة المدارية مع التيار الغربي والمنخفضات خارج المدارية عند انتقالها نحو العروض الوسطى."},{"type":"text","text":"يشير الانتقال خارج المداري إلى تحول بنية النظام المداري من مصدر طاقة حراري محيطي إلى نظام يتأثر بالتدرجات الحرارية والباروكلينية."},{"type":"text","text":"قد يتغير توزيع الرياح والهطول خلال الانتقال، وتصبح الأخطار ممتدة على مساحة أوسع أو غير متناظرة."},{"type":"text","text":"يسهم تفاعل الدوامية الكامنة مع الأخاديد العلوية في إعادة تنظيم بنية النظام وتطوره."},{"type":"text","text":"قد يؤدي اندماج الرطوبة المدارية مع جبهة أو أخدود إلى هطول غزير بعيد عن المركز الأصلي."},{"type":"text","text":"تؤثر سرعة التيار الغربي وقص الرياح وحرارة سطح البحر في توقيت ومسار الانتقال."},{"type":"text","text":"لا يعني الانتقال بالضرورة ضعف النظام فوراً؛ فقد يحتفظ برياح قوية أو يتعمق كمنخفض خارج مداري في ظروف معينة."},{"type":"text","text":"تستخدم خرائط الارتفاع والدوامية والحرارة والرطوبة وصور الأقمار لتتبع التحول البنيوي."},{"type":"text","text":"تحتاج توقعات المسار والشدة إلى مجموعات نماذج بسبب حساسية التفاعل بين النظام والتدفق المحيط."},{"type":"text","text":"تختلف الآثار الساحلية والداخلية بحسب المسار والتضاريس ومجال الهطول والرياح."},{"type":"text","text":"مثال: بقايا نظام مداري قد تعزز منخفضاً خارج مدارياً وتزيد إمداد الرطوبة إلى منطقة بعيدة عن مركزه السابق."},{"type":"callout","text":"خلاصة: التفاعل المداري-خارج المداري عملية ديناميكية تغير بنية النظام ومجال تأثيره."}]}',1430,60,'["شرح الانتقال خارج المداري","فهم تفاعل الدوامية والرطوبة","تفسير تغير بنية الإعصار"]','ديناميكية الغلاف الجوي المتقدمة'),
('forecast-sensitivity-and-predictability','حساسية التنبؤ وقابلية التنبؤ الجوي','اعتماد التوقع على الحالة الابتدائية وتطور الأخطاء وحدود المهلة الزمنية.','{"blocks":[{"type":"text","text":"تعبر قابلية التنبؤ عن مدى إمكانية تقدير تطور الغلاف الجوي مسبقاً ضمن حدود زمنية ومكانية معينة."},{"type":"text","text":"تتأثر قابلية التنبؤ بحساسية النظام للحالة الابتدائية وبالعمليات الفيزيائية والقيود الرصدية والنموذجية."},{"type":"text","text":"قد تنمو فروق صغيرة بين حالات ابتدائية متقاربة مع الزمن، خصوصاً في الأنظمة الديناميكية الحساسة."},{"type":"text","text":"تؤدي الأخطاء في الرصد أو التحليل إلى اختلاف في الحالة الابتدائية التي يبدأ منها النموذج."},{"type":"text","text":"تؤدي أخطاء التمثيل الفيزيائي والشبكة والحدود إلى اختلافات حتى عندما تكون الحالة الابتدائية متقاربة."},{"type":"text","text":"تختلف قابلية التنبؤ باختلاف الظاهرة؛ فقد يكون التنبؤ بالأنماط واسعة النطاق أكثر قابلية من توقيت خلية حملية مفردة."},{"type":"text","text":"تساعد مجموعات النماذج في تقدير انتشار الحلول وتحديد المناطق أو الفترات ذات عدم اليقين الأعلى."},{"type":"text","text":"قد تكون المجموعة غير ممثلة لجميع مصادر الخطأ، ولذلك لا يساوي انتشارها الحقيقي الكامل لعدم اليقين."},{"type":"text","text":"تتغير المهارة مع مهلة التنبؤ والموسم والمنطقة والمتغير الجوي."},{"type":"text","text":"تساعد دراسات الحالات والتحقق التاريخي على تحديد حدود التنبؤ لكل ظاهرة ومنطقة."},{"type":"text","text":"مثال: قد يتفق أعضاء المجموعة على وجود منخفض واسع لكن يختلفون في توقيت الجبهة وموقع أشد الهطول."},{"type":"callout","text":"خلاصة: التنبؤ ليس يقيناً مطلقاً، بل تقدير يتأثر بالحالة الابتدائية والنموذج وقابلية النظام للتنبؤ."}]}',1440,60,'["شرح قابلية التنبؤ","فهم نمو أخطاء الحالة الابتدائية","تمييز عدم اليقين الأولي والنموذجي"]','التنبؤ الممتد وقابلية التنبؤ'),
('ensemble-calibration-and-postprocessing','معايرة التنبؤات التجميعية والمعالجة اللاحقة','تحسين الاحتمالات وتصحيح الانحياز وتقييم موثوقية مجموعات النماذج.','{"blocks":[{"type":"text","text":"تهدف المعالجة اللاحقة إلى تحسين مخرجات النماذج باستخدام علاقات إحصائية مستمدة من بيانات تاريخية وتحقق مستقل."},{"type":"text","text":"قد تعاني مخرجات النماذج من انحياز ثابت أو متغير بحسب الموسم والمنطقة والمهلة والمتغير."},{"type":"text","text":"تستخدم المعايرة الاحتمالية لضبط توافق الاحتمالات المتوقعة مع التكرار الفعلي للأحداث على عينات كبيرة."},{"type":"text","text":"تساعد مخططات الموثوقية في كشف ما إذا كانت الاحتمالات أعلى أو أقل من التكرار المرصود."},{"type":"text","text":"تستخدم طرق مثل Model Output Statistics لربط مخرجات النموذج بالمشاهدات السابقة وفق متغيرات تفسيرية."},{"type":"text","text":"تستخدم بعض الأساليب تصحيح الانحياز أو تحويل التوزيعات أو إعادة معايرة الاحتمالات."},{"type":"text","text":"يجب فصل بيانات التدريب عن التحقق لتجنب تسرب المعلومات والمبالغة في تقدير الأداء."},{"type":"text","text":"تحتاج المعالجة اللاحقة إلى تحديث دوري عند تغير خصائص النموذج أو المناخ أو شبكة الرصد."},{"type":"text","text":"قد تحسن المعالجة الإحصائية بعض المقاييس، لكنها لا تصلح تلقائياً أخطاء البنية الفيزيائية أو الأحداث النادرة غير الممثلة."},{"type":"text","text":"يجب تقييم الأداء قبل المعالجة وبعدها على فترات مستقلة وبمقاييس متعددة."},{"type":"text","text":"مثال: يمكن معايرة احتمال تجاوز عتبة المطر من أرشيف توقعات سابق ومشاهدات موثوقة، ثم تقييم المعايرة على سنوات لم تدخل التدريب."},{"type":"callout","text":"خلاصة: المعالجة اللاحقة تحسن قابلية استخدام التوقعات بشرط تحقق مستقل وتوثيق حدود الطريقة."}]}',1450,60,'["شرح المعايرة الاحتمالية","فهم المعالجة اللاحقة","تقييم موثوقية المجموعة"]','التنبؤ الممتد وقابلية التنبؤ'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'ديناميكية الغلاف الجوي المتقدمة' then u1.id when 'التنبؤ الممتد وقابلية التنبؤ' then u2.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'التحليل الديناميكي المتقدم والتنبؤ الممتد',d.unit from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;